// Image-based camera: focus coordinates are measured in each original scene.
const anchors={courtyard:{moon:[.82,.15],lamps:[[.33,.23],[.60,.59],[.85,.53]]},lake:{moon:[.63,.17],lamps:[[.215,.22],[.48,.49],[.91,.51]]},mountain:{moon:[.82,.17],lamps:[[.20,.25],[.86,.74],[.45,.43]]}};
export class SceneCamera{
 constructor({onMemories,reduced}){
  this.onMemories=onMemories;this.reduced=reduced;this.scene='courtyard';this.imageSize=[1672,941];this.busy=false;this.sequence=0;this.anim=null;
  this.env=document.getElementById('environment');this.dialog=document.getElementById('scene-focus');this.canvas=document.getElementById('focus-dust');this.ctx=this.canvas.getContext('2d');
  document.getElementById('focus-close').onclick=()=>this.close();this.dialog.addEventListener('cancel',e=>{e.preventDefault();this.close();});
  document.getElementById('focus-memories').onclick=async()=>{if(this.busy)return;const action=this.action;if(await this.close())action?.();};
  this.stars=Array.from({length:140},()=>({angle:Math.random()*Math.PI*2,r:Math.random(),speed:.12+Math.random()*.5,size:.5+Math.random()*2,phase:Math.random()*6.28}));
  this.resize=()=>{if(this.dialog.open)this.cancel();this.layout();};window.addEventListener('resize',this.resize);
 }
 setScene(name,width,height){this.cancel();this.scene=anchors[name]?name:'courtyard';this.imageSize=[width||1672,height||941];this.layout();}
 position(kind,index=0){const a=kind==='moon'?anchors[this.scene].moon:anchors[this.scene].lamps[index];const w=innerWidth*1.04,h=innerHeight*1.04;const scale=Math.max(w/this.imageSize[0],h/this.imageSize[1]);const align=innerWidth<=700?.83:.75;return{x:-innerWidth*.02+(w-this.imageSize[0]*scale)*align+a[0]*this.imageSize[0]*scale,y:-innerHeight*.02+(h-this.imageSize[1]*scale)*.5+a[1]*this.imageSize[1]*scale};}
 layout(){const moon=this.position('moon');const button=document.getElementById('moon-hotspot');button.style.left=Math.max(50,Math.min(innerWidth-70,moon.x))+'px';button.style.top=Math.max(160,Math.min(innerHeight-150,moon.y))+'px';document.querySelectorAll('.reunion-lantern').forEach((b,i)=>{const p=this.position('lamp',i);b.style.left=Math.max(innerWidth<=700?60:110,Math.min(innerWidth-(innerWidth<=700?60:110),p.x))+'px';b.style.top=Math.max(Math.min(310,innerHeight*.4),Math.min(innerHeight-240,p.y))+'px';});}
 async open({kind='lamp',index=0,title,text,source,actionLabel,action}){
  if(this.dialog.open||this.busy)return;this.busy=true;const token=++this.sequence;this.source=source;this.kind=kind;this.action=kind==='lamp'?action:this.onMemories;const nextButton=document.getElementById('focus-memories');nextButton.hidden=kind==='lamp'&&!action;nextButton.textContent=kind==='lamp'?(actionLabel||'点亮下一盏灯 →'):'展开月光里的回忆 ↗';
  document.getElementById('focus-kicker').textContent=kind==='moon'?'把牵挂，轻轻寄给月光':'灯亮了，心意也近了';document.getElementById('focus-title').textContent=title;document.getElementById('focus-text').textContent=text;
  this.dialog.dataset.kind=kind;this.dialog.classList.remove('revealed');document.body.classList.add('cinematic-active');this.dialog.showModal();document.getElementById('focus-close').focus();
  this.origin=this.position(kind,index);if(kind==='lamp'&&source){const rect=source.getBoundingClientRect();this.origin={x:rect.x+rect.width/2,y:rect.y+rect.height/2-10};}this.target={x:innerWidth*(innerWidth<700?.5:this.origin.x>innerWidth*.6?.70:.30),y:innerHeight*(innerWidth<700?.28:.43)};
  const reduce=this.reduced();this.duration=reduce?160:1450;this.started=performance.now();this.progress=0;
  const zoom=reduce?1:kind==='moon'?(innerWidth<700?1.8:2.65):2.05;
  // Transform origin is top-left of the oversized background, including its -2% offset.
  const dx=reduce?0:Math.max(innerWidth*(1.02-1.04*zoom),Math.min(innerWidth*.02,this.target.x-this.origin.x*zoom+innerWidth*.02*(1-zoom))),dy=reduce?0:Math.max(innerHeight*(1.02-1.04*zoom),Math.min(innerHeight*.02,this.target.y-this.origin.y*zoom+innerHeight*.02*(1-zoom)));
  this.target={x:this.origin.x*zoom+dx-innerWidth*.02*(1-zoom),y:this.origin.y*zoom+dy-innerHeight*.02*(1-zoom)};
  this.dialog.dataset.side=this.target.x>innerWidth*.5?'right':'left';document.body.dataset.focusSide=this.dialog.dataset.side;
  if(kind==='lamp'&&source){this.lamp=source.cloneNode(true);this.lamp.removeAttribute('aria-label');this.lamp.removeAttribute('aria-pressed');this.lamp.tabIndex=-1;this.lamp.setAttribute('aria-hidden','true');this.lamp.classList.add('focus-lantern','lit');this.lamp.style.left=this.origin.x+'px';this.lamp.style.top=this.origin.y+'px';this.dialog.append(this.lamp);this.lampAnimation=this.lamp.animate([{left:this.origin.x+'px',top:this.origin.y+'px',transform:'translate(-50%,-50%) scale(1)'},{left:this.target.x+'px',top:this.target.y+'px',transform:`translate(-50%,-50%) scale(${reduce?1:1.65})`}],{duration:this.duration,easing:'cubic-bezier(.22,.7,.16,1)',fill:'forwards'});}
  this.endTransform=`translate(${dx}px,${dy}px) scale(${zoom})`;
  this.anim=this.env.animate([{transform:'translate(0,0) scale(1)'},{transform:this.endTransform}],{duration:this.duration,easing:'cubic-bezier(.22,.7,.16,1)',fill:'forwards'});
  this.canvas.width=innerWidth*Math.min(devicePixelRatio,1.5);this.canvas.height=innerHeight*Math.min(devicePixelRatio,1.5);this.ctx.setTransform(this.canvas.width/innerWidth,0,0,this.canvas.height/innerHeight,0,0);this.draw();
  try{await this.anim.finished;}catch{return;}if(token!==this.sequence)return;this.busy=false;this.dialog.classList.add('revealed');
 }
 draw(){if(!this.dialog.open)return;const now=performance.now(),raw=Math.min(1,(now-this.started)/this.duration),p=1-Math.pow(1-raw,3);const c=this.ctx;c.clearRect(0,0,innerWidth,innerHeight);const reduce=this.reduced();const x=reduce?this.origin.x:this.origin.x+(this.target.x-this.origin.x)*p,y=reduce?this.origin.y:this.origin.y+(this.target.y-this.origin.y)*p;const t=reduce?0:now*.001;const radius=this.kind==='moon'?Math.min(innerWidth,innerHeight)*.17:95;
  const glow=c.createRadialGradient(x,y,0,x,y,radius*1.8);glow.addColorStop(0,this.kind==='moon'?'rgba(191,215,255,.10)':'rgba(255,182,78,.17)');glow.addColorStop(1,'rgba(255,214,130,0)');c.fillStyle=glow;c.fillRect(0,0,innerWidth,innerHeight);
  for(const s of this.stars){const r=radius*(.55+s.r*1.3)*(0.6+p*.4),a=s.angle+t*s.speed*.18;const sx=x+Math.cos(a)*r,sy=y+Math.sin(a)*r*.8-(reduce?0:Math.sin(t*s.speed+s.phase)*12);c.globalAlpha=(.25+.55*(.5+.5*Math.sin(t+s.phase)))*p;c.fillStyle=this.kind==='moon'?'#dbeaff':'#ffe1a1';c.beginPath();c.arc(sx,sy,s.size,0,Math.PI*2);c.fill();}c.globalAlpha=1;this.raf=requestAnimationFrame(()=>this.draw());
 }
 async close(){if(!this.dialog.open)return;const token=++this.sequence;this.busy=true;this.dialog.classList.remove('revealed');if(this.lamp){const style=getComputedStyle(this.lamp);const from={left:style.left,top:style.top,transform:style.transform};this.lampAnimation?.cancel();this.lampAnimation=this.lamp.animate([from,{left:this.origin.x+'px',top:this.origin.y+'px',transform:'translate(-50%,-50%) scale(1)',opacity:0}],{duration:this.reduced()?120:850,easing:'cubic-bezier(.22,.7,.16,1)',fill:'forwards'});}const current=getComputedStyle(this.env).transform;this.anim?.cancel();this.anim=this.env.animate([{transform:current},{transform:'translate(0,0) scale(1)'}],{duration:this.reduced()?120:850,easing:'cubic-bezier(.22,.7,.16,1)',fill:'forwards'});try{await this.anim.finished;}catch{return;}if(token!==this.sequence)return;this.cancel();this.source?.focus({preventScroll:true});return true;}
 cancel(){this.sequence++;this.lampAnimation?.cancel();this.lamp?.remove();this.lamp=null;this.anim?.cancel();this.anim=null;cancelAnimationFrame(this.raf);this.busy=false;this.dialog.classList.remove('revealed');if(this.dialog.open)this.dialog.close();document.body.classList.remove('cinematic-active');}
}
